import {owner} from './extra-data.js';
import {icon} from './app.js';
export function contactLinks(){return `<div class="contact-links"><a class="contact-link" href="${owner.instagram}" target="_blank" rel="noopener noreferrer"><span class="contact-logo">${icon('instagram')}</span><span><strong>Instagram</strong><small dir="ltr">@alae_rdd</small></span>${icon('chevron')}</a><a class="contact-link" href="${owner.facebook}" target="_blank" rel="noopener noreferrer"><span class="contact-logo">${icon('facebook')}</span><span><strong>Facebook</strong><small>Alae Rdd</small></span>${icon('chevron')}</a><a class="contact-link" href="mailto:${owner.email}"><span class="contact-logo">${icon('mail')}</span><span><strong>Email</strong><small dir="ltr">${owner.email}</small></span>${icon('chevron')}</a></div>`;}
